    for (let k = 0; k < ids.length; k++) { s += w(ids[k]); c[k] = s; }
    const x = R() * s; let lo = 0, hi = ids.length - 1;
    while (lo < hi) { const m = (lo + hi) >> 1; if (c[m] < x) lo = m + 1; else hi = m; }
